#!/usr/bin/env node
/*
 * Loopback agent for the local browser.
 *
 * Runs INSIDE the dev container.  The host-side browser backend cannot reach services that listen
 * only on the container's 127.0.0.1, so it opens a tiny authenticated tunnel to this agent and the
 * agent makes the final connection to loopback for it.
 *
 * Protocol (one line, then raw bytes):
 *   CONNECT <port> <token>  ->  OK\n                  followed by a bidirectional byte stream
 *   PORTS <token>           ->  PORTS <json>\n        listening ports, for the browser start page
 *   PING <token>            ->  PONG\n
 *
 * It is intentionally not an HTTP proxy: a target is always a numeric loopback port.  The token is
 * generated by boot and passed in the environment so the agent cannot be used by other containers
 * or by a stray process on the bridge network.
 *
 * No dependencies: Node 18+ only.
 */
'use strict';

const net = require('net');
const crypto = require('crypto');
const { execFile } = require('child_process');

const env = process.env;
const PORT = parseInt(env.LOCAL_AGENT_PORT || '7705', 10);
const HOST = env.LOCAL_AGENT_HOST || '0.0.0.0';
const TOKEN = env.LOCAL_AGENT_TOKEN || '';
const EXCLUDE_PORTS = new Set(String(env.LOCAL_AGENT_EXCLUDE_PORTS || '')
  .split(',').map(x => parseInt(x, 10)).filter(n => Number.isInteger(n) && n > 0));
// Infrastructure that is useful to the session but not a local web app worth listing.
const EXCLUDE_PROCESSES = new Set(String(env.LOCAL_AGENT_EXCLUDE_PROCESSES ||
  'opencode,cloudflared,chrome-headless')
  .split(',').map(x => x.trim().toLowerCase()).filter(Boolean));
const MAX_LINE = 512;
const MAX_CLIENTS = 512;
const CONNECT_TIMEOUT = 5000;
const IDLE_TIMEOUT = 10 * 60 * 1000;

if (!TOKEN || TOKEN.length < 16) {
  console.error('[local-agent] LOCAL_AGENT_TOKEN is missing or too short');
  process.exit(1);
}
if (!Number.isInteger(PORT) || PORT < 1 || PORT > 65535) {
  console.error('[local-agent] invalid port');
  process.exit(1);
}

const tokenBuf = Buffer.from(TOKEN);
const safeEqual = value => {
  const b = Buffer.from(String(value || ''));
  return b.length === tokenBuf.length && crypto.timingSafeEqual(b, tokenBuf);
};

function parsePort(value) {
  if (!/^[0-9]{1,5}$/.test(value)) return 0;
  const n = parseInt(value, 10);
  return n >= 1 && n <= 65535 ? n : 0;
}

function sendLine(socket, line) {
  if (!socket.destroyed) socket.write(line + '\n');
}

/* ---------------------------------------------------------------- port listing */

let portsCache = { at: 0, value: [] };

function parseSs(text) {
  const out = new Map();
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line.startsWith('LISTEN')) continue;
    const fields = line.split(/\s+/);
    // LISTEN 0 4096 127.0.0.1:8099 0.0.0.0:* users:(("php",pid=123,fd=3))
    if (fields.length < 4) continue;
    const local = fields[3];
    const cut = local.lastIndexOf(':');
    if (cut < 1) continue;
    const port = parsePort(local.slice(cut + 1));
    if (!port || port === PORT) continue;
    let address = local.slice(0, cut);
    if (address === '*' || address === '0.0.0.0' || address === '::' || address === '[::]') address = '*';
    const proc = line.match(/users:\(\("([^"]+)",pid=([0-9]+)/);
    const item = {
      port,
      address,
      process: proc ? proc[1] : null,
      pid: proc ? parseInt(proc[2], 10) : null,
    };
    const prev = out.get(port);
    if (!prev || (prev.process === null && item.process !== null)) out.set(port, item);
  }
  return [...out.values()].sort((a, b) => a.port - b.port);
}

function parseProcNet(file, v6) {
  let text;
  try { text = require('fs').readFileSync(file, 'utf8'); } catch { return []; }
  const out = [];
  for (const line of text.split('\n').slice(1)) {
    const fields = line.trim().split(/\s+/);
    if (fields.length < 4 || fields[3] !== '0A') continue; // 0A = LISTEN
    const local = fields[1];
    const cut = local.lastIndexOf(':');
    if (cut < 0) continue;
    const port = parseInt(local.slice(cut + 1), 16);
    if (!port || port === PORT) continue;
    let address = local.slice(0, cut);
    if (!v6) {
      const bytes = address.match(/../g).reverse().join('');
      address = [0, 2, 4, 6].map(i => parseInt(bytes.slice(i, i + 2), 16)).join('.');
    } else {
      address = '::';
    }
    if (address === '0.0.0.0') address = '*';
    out.push({ port, address, process: null, pid: null });
  }
  return out;
}

function listPorts(cb) {
  const now = Date.now();
  if (now - portsCache.at < 1500) return cb(null, portsCache.value);
  execFile('ss', ['-ltnp'], { timeout: 3000, maxBuffer: 2 * 1024 * 1024 }, (err, stdout) => {
    let list;
    if (!err) {
      list = parseSs(stdout);
    } else {
      const v4 = parseProcNet('/proc/net/tcp', false);
      const v6 = parseProcNet('/proc/net/tcp6', true);
      const seen = new Set();
      list = [];
      for (const p of [...v4, ...v6]) {
        if (seen.has(p.port)) continue;
        seen.add(p.port);
        list.push(p);
      }
      list.sort((a, b) => a.port - b.port);
    }
    if (EXCLUDE_PORTS.size) list = list.filter(p => !EXCLUDE_PORTS.has(p.port));
    if (EXCLUDE_PROCESSES.size) list = list.filter(p => {
      const name = String(p.process || '').toLowerCase().replace(/\.exe$/, '');
      return !name || !EXCLUDE_PROCESSES.has(name);
    });
    portsCache = { at: now, value: list };
    cb(null, list);
  });
}

/* ---------------------------------------------------------------- connection bridge */

function connectLoopback(port, cb) {
  const addresses = ['127.0.0.1', '::1'];
  let index = 0;
  const tryNext = lastErr => {
    if (index >= addresses.length) return cb(lastErr || new Error('not listening'));
    const host = addresses[index++];
    const target = net.connect({ host, port });
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      target.destroy();
      tryNext(new Error('timed out'));
    }, CONNECT_TIMEOUT);
    target.once('connect', () => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      target.removeAllListeners('error');
      cb(null, target);
    });
    target.once('error', err => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      target.destroy();
      tryNext(err);
    });
  };
  tryNext();
}

function bridge(client, target, rest) {
  client.setTimeout(0);
  target.setTimeout(0);
  target.setNoDelay(true);
  client.setNoDelay(true);
  const close = () => {
    client.destroy();
    target.destroy();
  };
  client.on('error', close);
  target.on('error', close);
  client.on('close', close);
  target.on('close', close);
  if (rest && rest.length) target.write(rest);
  target.pipe(client);
  client.pipe(target);
}

/* ---------------------------------------------------------------- server */

let clients = 0;
const server = net.createServer(client => {
  if (clients >= MAX_CLIENTS) { client.destroy(); return; }
  clients++;
  client.on('close', () => { clients--; });
  client.setNoDelay(true);
  client.setTimeout(IDLE_TIMEOUT);

  let buf = Buffer.alloc(0);
  let handled = false;
  const timer = setTimeout(() => client.destroy(), 5000);

  const fail = line => {
    clearTimeout(timer);
    sendLine(client, 'ERR ' + line);
    client.end();
  };

  const onData = chunk => {
    if (handled) return;
    buf = Buffer.concat([buf, chunk]);
    if (buf.length > MAX_LINE) return fail('line too long');
    const newline = buf.indexOf(0x0a);
    if (newline < 0) return;
    handled = true;
    clearTimeout(timer);
    client.pause();
    client.removeListener('data', onData);

    const line = buf.subarray(0, newline).toString('utf8').replace(/\r$/, '');
    const rest = buf.subarray(newline + 1);
    const parts = line.split(' ');

    if (parts[0] === 'PING') {
      if (!safeEqual(parts[1])) return fail('auth');
      sendLine(client, 'PONG');
      return client.end();
    }
    if (parts[0] === 'PORTS') {
      if (!safeEqual(parts[1])) return fail('auth');
      return listPorts((err, list) => {
        if (err) return fail('ports');
        sendLine(client, 'PORTS ' + JSON.stringify(list));
        client.end();
      });
    }
    if (parts[0] === 'CONNECT') {
      if (!safeEqual(parts[2])) return fail('auth');
      const port = parsePort(parts[1] || '');
      if (!port) return fail('bad port');
      if (port === PORT) return fail('recursive');
      connectLoopback(port, (err, target) => {
        if (err) return fail('target ' + (err.code || err.message || 'unreachable'));
        if (client.destroyed) { target.destroy(); return; }
        sendLine(client, 'OK');
        bridge(client, target, rest);
      });
      return;
    }
    fail('unknown command');
  };

  client.on('data', onData);
  client.once('close', () => {
    clearTimeout(timer);
    client.removeListener('data', onData);
  });
});

server.on('error', err => {
  console.error('[local-agent] ' + err.message);
  process.exit(1);
});

server.listen(PORT, HOST, () => {
  console.log(`[local-agent] listening on ${HOST}:${PORT}`);
});

const shutdown = () => { server.close(() => process.exit(0)); setTimeout(() => process.exit(0), 1000).unref(); };
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
